import numpy as np
import pandas as pd

def task_func(rows, columns=["A", "B", "C", "D", "E"], seed=0) -> pd.DataFrame:
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be an integer")
    if rows < 0:
        raise ValueError("rows must be non-negative")

    if isinstance(columns, (str, bytes)):
        raise TypeError("columns must be an iterable of column labels, not a string")

    try:
        cols = list(columns)
    except TypeError as exc:
        raise TypeError("columns must be an iterable of column labels") from exc

    unique_cols = list(dict.fromkeys(cols))
    try:
        unique_cols.sort()
    except TypeError:
        unique_cols.sort(key=lambda x: str(x))

    rng = np.random.default_rng(seed)
    data = rng.random((rows, len(unique_cols)))
    return pd.DataFrame(data, columns=unique_cols)
